#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-10-08

# Test: a shell test that runs `git commit` must turn commit signing off (#4664)
#
# Fixture repos inherit the developer's global git config. With
# commit.gpgsign=true and an ssh signer such as 1Password, a locked signer
# fails the commit, so the test result depends on the machine. On 2026-10-07
# that blocked a pre-push (test-skill-scripts-errexit.sh). This lint fails any
# tests/**/*.sh that commits without one of the accepted isolation forms:
#   - git_isolate         (tests/fixtures/git-isolate.sh)
#   - GIT_CONFIG_GLOBAL=  (an isolated global config)
#   - commit.gpgsign      (set to false on the repo or the command)
#   - tag.gpgsign         (set to false, for a tag)
# Comments do not count, and the lint skips itself.
#
# A signing operation is a commit, a merge that makes a commit (not
# --ff-only, --squash or --abort) or a signed or annotated tag (-s, -a, -u),
# run by git or by a function whose body runs git (#4674). It counts at a
# command position, also in an if/elif/while/until/! condition, and also when
# a line continuation splits it. `git -C <dir> config ... false` isolates
# <dir> only; the other forms isolate every later line.
#
# Usage: test-git-commit-isolation.sh [tests-dir]   (default: this repo's tests/)

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TESTS_DIR="${1:-$(cd "$SCRIPT_DIR/.." && pwd)}"

FAILED=0
CHECKED=0

# Only real command lines count. Comments are blanked first (see
# code_lines), so a comment that names the fix does not satisfy the lint.
# A commit is git (with optional env prefixes and -C/-c options) at a command
# position: line start, or after ; & | ( or then/do/else. Text inside a message
# ("... runs git commit ...") is not a command position.
ENV_PREFIX='([A-Za-z_][A-Za-z0-9_]*=[^[:space:]]*[[:space:]]+)*'
# Commands that run their arguments (env -u X git ...); EXEC_RE adds the
# file's own functions whose body runs "$@" (git_env git ...).
exec_prefix() {
  echo "((${1})([[:space:]]+(-u[[:space:]]+[^[:space:]]+|-[^[:space:]]+|[A-Za-z_][A-Za-z0-9_]*=[^[:space:]]*))*[[:space:]]+)?"
}
CMD_POS='(^|[;&|(!]|\b(then|do|else|if|elif|while|until)\b)[[:space:]]*'
# An option value may be quoted and hold spaces: -c user.name='A B'.
OPT_VAL="([^[:space:]'\"]|'[^']*'|\"[^\"]*\")+"
GIT_OPTS="([[:space:]]+-[Cc][[:space:]]+${OPT_VAL})*"
# The signing subcommands. A merge or tag line is a signing operation only
# if it passes is_signing_line below.
OPS='(commit\b|merge([[:space:]]|$)|tag([[:space:]]|$))'
# Accepted isolation, also as commands: a git_isolate call, an isolated
# global config, or signing set to false.
ISOLATE_RE="${CMD_POS}git_isolate\b|GIT_CONFIG_GLOBAL=|(commit|tag)\.gpgsign(=|[[:space:]]+)false"
SELF="$SCRIPT_DIR/$(basename "${BASH_SOURCE[0]}")"

# Print the file with comments blanked, one output line per input line so
# line numbers stay true. A # starts a comment only outside quotes and at the
# start of a word, so `echo "log #1"; git commit` keeps its commit.
code_lines() {
  awk '{
    out = ""; q = ""; n = length($0)
    for (i = 1; i <= n; i++) {
      ch = substr($0, i, 1)
      if (q == "") {
        if (ch == "#" && (i == 1 || substr($0, i - 1, 1) ~ /[[:space:];&|(]/)) break
        if (ch == "\\") { out = out ch substr($0, i + 1, 1); i++; continue }
        if (ch == "\047" || ch == "\"") q = ch
      } else if (ch == q) {
        q = ""
      } else if (q == "\"" && ch == "\\") {
        out = out ch substr($0, i + 1, 1); i++; continue
      }
      out = out ch
    }
    print out
  }' "$1"
}

# Join `\` continuations so a command split over lines is one line. The
# joined text sits on the first line's number and the lines it absorbed print
# empty, so line numbers stay true.
join_continuations() {
  awk '{
    if (buf != "") { buf = buf " " $0; extra++ } else { buf = $0 }
    if (buf ~ /\\$/) { sub(/\\$/, "", buf); next }
    print buf; for (i = 0; i < extra; i++) print ""
    buf = ""; extra = 0
  } END { if (buf != "") print buf }' "$1"
}

# Functions whose body runs git: one line per function, "name iso", where
# iso is 1 when the body itself turns signing off. One-line bodies and
# bodies closed by a lone } line are read.
git_wrappers() {
  awk '
  function flush() {
    if (name != "" && name != "git" && name != "git_isolate" && body ~ /(^|[^A-Za-z0-9_.\/-])git([ \t]|$)/)
      print name, (body ~ /GIT_CONFIG_GLOBAL=|(commit|tag)\.gpgsign(=|[ \t]+)false|git_isolate/ ? 1 : 0), "git"
    else if (name != "" && body ~ /"\$@"/)
      print name, 0, "exec"
    name = ""; body = ""
  }
  name == "" && match($0, /^[ \t]*(function[ \t]+)?[A-Za-z_][A-Za-z0-9_]*[ \t]*\(\)/) {
    hdr = substr($0, RSTART, RLENGTH)
    sub(/^[ \t]*(function[ \t]+)?/, "", hdr); sub(/[ \t]*\(\)$/, "", hdr)
    name = hdr; body = substr($0, RSTART + RLENGTH)
    if (body ~ /}[ \t;]*$/) flush()
    next
  }
  name != "" { body = body "\n" $0; if ($0 ~ /^[ \t]*}[ \t]*$/) flush() }
  END { flush() }' "$1"
}

# A merge counts unless it makes no commit; a tag counts only signed or
# annotated. A commit always counts.
is_signing_line() {
  local line="$1"
  if grep -Eq "${CMD_POS}${ENV_PREFIX}${RUNNER_RE}${GIT_OPTS}([[:space:]]+-c[[:space:]]+[^[:space:]]+)*[[:space:]]+commit\b" <<< "$line"; then return 0; fi
  if grep -Eq "${CMD_POS}${ENV_PREFIX}${RUNNER_RE}${GIT_OPTS}([[:space:]]+-c[[:space:]]+[^[:space:]]+)*[[:space:]]+merge([[:space:]]|$)" <<< "$line"; then
    grep -Eq -- '--ff-only|--squash|--abort|--quit' <<< "$line" || return 0
  fi
  if grep -Eq "${CMD_POS}${ENV_PREFIX}${RUNNER_RE}${GIT_OPTS}([[:space:]]+-c[[:space:]]+[^[:space:]]+)*[[:space:]]+tag([[:space:]]|$)" <<< "$line"; then
    grep -Eq -- '[[:space:]](-[a-zA-Z]*[sau][a-zA-Z]*|--sign|--annotate|--local-user)\b' <<< "$line" && return 0
  fi
  return 1
}

# The -C <dir> of a line, or empty.
c_dir() { sed -nE 's/.*[[:space:]]-C[[:space:]]+([^[:space:]]+).*/\1/p' <<< "$1" | head -1; }

# Every signing operation must be covered: its own line turns signing off,
# it runs through a wrapper whose body does, or an isolation line comes
# before it. `git -C <dir> config ... false` covers later lines on <dir>
# only. A git_isolate call after the operation does not cover it, because
# the operation already reached the signer.
uncovered_commit() {
  local n line iso_n iso_line dir covered
  while IFS=: read -r n line; do
    is_signing_line "$line" || continue
    if grep -Eq "$ISOLATE_RE" <<< "$line"; then continue; fi
    if [[ -n "$ISO_WRAPPERS_RE" ]] && grep -Eq "${CMD_POS}${ENV_PREFIX}(${ISO_WRAPPERS_RE})\b" <<< "$line"; then continue; fi
    covered=0
    dir="$(c_dir "$line")"
    while IFS=: read -r iso_n iso_line; do
      [[ "$iso_n" -lt "$n" ]] || break
      if grep -Eq "git${GIT_OPTS}[[:space:]]+config\b" <<< "$iso_line" && ! grep -Eq -- '--global' <<< "$iso_line"; then
        local idir
        idir="$(c_dir "$iso_line")"
        # Only two literal dirs compare; a variable dir ("$1") is unknown
        # here, so it covers every later line, as before #4674.
        if [[ -n "$idir" && "$idir" != *'$'* && "$idir" != "$dir" ]]; then continue; fi
      fi
      covered=1
      break
    done < <(grep -nE "$ISOLATE_RE" "$1" | grep -v -E "^($WRAPPER_LINES):" || true; grep -nE "$ISOLATE_RE" "$1" | grep -E "^($WRAPPER_LINES):" | grep -E "git_isolate|[[:space:]]config[[:space:]]|(^[0-9]+:|[;&|(]|\bthen\b|\bdo\b)[[:space:]]*export[[:space:]]" || true)
    [[ "$covered" -eq 1 ]] && continue
    echo "$n"
    return 0
  done < <(grep -nE "$OPS_LINE_RE" "$1" || true)
}

# Line numbers inside function bodies. An inline -c or env prefix there
# covers only calls through that function, never the lines after it; a
# git_isolate call, an export or a git config line in a body still counts
# as setup.
wrapper_body_lines() {
  awk '
  name == "" && /^[ \t]*(function[ \t]+)?[A-Za-z_][A-Za-z0-9_]*[ \t]*\(\)/ {
    name = 1; lines = NR
    if ($0 ~ /}[ \t;]*$/) { print lines; name = "" }
    next
  }
  name != "" { lines = lines "|" NR; if ($0 ~ /^[ \t]*}[ \t]*$/) { print lines; name = "" } }' "$1" | paste -sd'|' -
}

# The blanked copy goes to a file, never into `code_lines | grep -q`: under
# pipefail grep -q exits on the first match, awk takes SIGPIPE, and a long file
# reads as "no commit" (measured: two eval scripts dropped out that way).
CODE="$(mktemp "${TMPDIR:-/tmp}/ork-commit-iso.XXXXXX")"
trap 'rm -f "$CODE" "$CODE.raw"' EXIT

while IFS= read -r -d '' f; do
  # The lint quotes the patterns it looks for; never count it.
  [[ "$f" -ef "$SELF" ]] && continue
  code_lines "$f" > "$CODE.raw"
  join_continuations "$CODE.raw" > "$CODE"
  # The runners of this file: git, and every function whose body runs git.
  WRAPPERS="$(git_wrappers "$CODE")"
  RUNNER_RE="(git"
  ISO_WRAPPERS_RE=""
  EXEC_NAMES="env|command|exec|time|nice"
  while read -r wname wiso wkind; do
    [[ -n "$wname" ]] || continue
    if [[ "$wkind" == exec ]]; then EXEC_NAMES="$EXEC_NAMES|$wname"; continue; fi
    RUNNER_RE="$RUNNER_RE|$wname"
    [[ "$wiso" == 1 ]] && ISO_WRAPPERS_RE="${ISO_WRAPPERS_RE:+$ISO_WRAPPERS_RE|}$wname"
  done <<< "$WRAPPERS"
  RUNNER_RE="$(exec_prefix "$EXEC_NAMES")$RUNNER_RE)"
  WRAPPER_LINES="$(wrapper_body_lines "$CODE")"
  [[ -n "$WRAPPER_LINES" ]] || WRAPPER_LINES='0'
  OPS_LINE_RE="${CMD_POS}${ENV_PREFIX}${RUNNER_RE}${GIT_OPTS}([[:space:]]+-c[[:space:]]+[^[:space:]]+)*[[:space:]]+${OPS}"
  has_signing=0
  while IFS=: read -r _n _line; do
    if is_signing_line "$_line"; then has_signing=1; break; fi
  done < <(grep -nE "$OPS_LINE_RE" "$CODE" || true)
  [[ "$has_signing" -eq 1 ]] || continue
  CHECKED=$((CHECKED + 1))
  bad="$(uncovered_commit "$CODE")"
  if [[ -n "$bad" ]]; then
    echo "FAIL: ${f#"$TESTS_DIR"/}:$bad: commits, merges or tags before signing is turned off (source tests/fixtures/git-isolate.sh and call git_isolate first)"
    FAILED=1
  fi
done < <(find "$TESTS_DIR" -name fixtures -prune -o -type f -name '*.sh' -print0)

if [[ $CHECKED -eq 0 ]]; then
  echo "FAIL: no shell test under $TESTS_DIR runs git commit; the scan is broken"
  exit 1
fi
if [[ $FAILED -eq 0 ]]; then
  echo "OK: $CHECKED committing shell tests turn signing off"
fi
exit "$FAILED"
